namespace Ares.Structs.Game.World;

/// <summary>
/// The game's world item class list. The game state flags classes for the client to load by their index in it
/// (<c>PossibleWorldItemClassIndexBitFields</c>).
/// </summary>
public static class WorldItemList
{
    /// <summary>Bits per bitfield word.</summary>
    public const int WordBits = 64;

    /// <summary>Class paths, in list order: a class's index is its bit.</summary>
    public static IReadOnlyList<string> Classes { get; } =
    [
        .. WorldItemListPart0.Entries,
        .. WorldItemListPart1.Entries,
    ];

    private static readonly Dictionary<string, int> s_indexes = Classes.Select((path, index) => (path, index)).ToDictionary(entry => entry.path, entry => entry.index, StringComparer.Ordinal);

    /// <summary>Number of bitfield words the client allocates for the list.</summary>
    public static int WordCount => (Classes.Count / WordBits) + 1;

    /// <summary>The index of a class in the list, or null when the list does not hold it.</summary>
    /// <param name="classPath">Class path (<c>/Game/Path/BP_Name.BP_Name_C</c>).</param>
    /// <returns>The index, or null.</returns>
    public static int? IndexOf(string classPath)
    {
        return s_indexes.TryGetValue(classPath, out int index) ? index : null;
    }
}

